import{chemistry}from'../chemistry11-math.js';import{B,read,C,path,circle}from'../ten-utils.js';
export const readingSpec=[['Amount of water','जल की मात्रा','moles','mol'],['Water formed','बना जल','water','mol'],['Molar concentration','मोलर सांद्रता','concentration','mol/L'],['Hydrogen level energy','हाइड्रोजन स्तर की ऊर्जा','energy','eV'],['de Broglie wavelength','दे ब्रॉग्ली तरंगदैर्घ्य','wavelength','m'],['Orbitals in subshell','उपकोश में कक्षक','orbitals',''],['Symbolic radius index','सांकेतिक त्रिज्या सूचकांक','radiusIndex',''],['First ionisation enthalpy','प्रथम आयनन एन्थैल्पी','enthalpy','kJ/mol'],['Symbolic radius index','सांकेतिक त्रिज्या सूचकांक','radiusIndex',''],['Bond angle','आबंध कोण','angle','°'],['Resultant dipole','परिणामी द्विध्रुव','dipole','D'],['Bond order','आबंध कोटि','bondOrder',''],['Change in internal energy','आंतरिक ऊर्जा परिवर्तन','internal','J'],['Total enthalpy change','कुल एन्थैल्पी परिवर्तन','enthalpy','kJ/mol'],['Gibbs energy change','गिब्स ऊर्जा परिवर्तन','gibbs','kJ/mol'],['Reaction quotient Qc','अभिक्रिया भागफल Qc','quotient',''],['Hydrogen ion concentration','हाइड्रोजन आयन सांद्रता','hydrogen','mol/L'],['Hydrogen ion concentration','हाइड्रोजन आयन सांद्रता','hydrogen','mol/L'],['Central atom oxidation number','केंद्रीय परमाणु की ऑक्सीकरण संख्या','oxidation',''],['Electrons transferred','स्थानांतरित इलेक्ट्रॉन','electronMoles','mol'],['Electron loss from Fe2+','Fe2+ से इलेक्ट्रॉन त्याग','electronLoss',''],['Ideal bond angle','आदर्श आबंध कोण','angle','°'],['Qualitative effect index','गुणात्मक प्रभाव सूचकांक','effectIndex',''],['Rf value','Rf मान','rf',''],['Hydrogen count in alkane','ऐल्केन में हाइड्रोजन संख्या','alkaneH',''],['Relative torsional energy index','सापेक्ष मरोड़ ऊर्जा सूचकांक','energyIndex',''],['Reaction choice','अभिक्रिया चयन','index','']];
const secondary={0:['Particles','कण','particles',''],1:['Hydrogen remaining','शेष हाइड्रोजन','leftH2','mol'],3:['Excitation from ground state','मूल अवस्था से उत्तेजन','excitation','eV'],5:['Subshell electron capacity','उपकोश की इलेक्ट्रॉन क्षमता','capacity',''],8:['Ion charge','आयन का आवेश','ionCharge','e'],9:['Central lone pairs','केंद्रीय एकाकी युग्म','lonePairs',''],11:['Antibonding electrons','प्रतिआबंधन इलेक्ट्रॉन','antibonding',''],12:['Work on system','निकाय पर कार्य','work','J'],15:['Kc','Kc','equilibrium',''],16:['pH','pH','pH',''],17:['pH','pH','pH',''],19:['Copper deposited','जमा कॉपर','copperMoles','mol'],20:['Electron gain by Mn','Mn द्वारा इलेक्ट्रॉन ग्रहण','electronGain',''],21:['Pi bonds in examples','उदाहरणों में पाई आबंध','pi',''],24:['Alkene hydrogen count','ऐल्कीन में हाइड्रोजन संख्या','alkeneH','']};
const fmt=x=>Math.abs(x)>0&&(Math.abs(x)<.01||Math.abs(x)>=1e6)?x.toExponential(3):Number(x.toFixed(4)).toString();
const molecule=(g,centre,atoms,color=C.blue,terminal=B('H','H'),terminalColor=C.white)=>{g.sphere(...centre,.18,color);for(const a of atoms){let p=a.map((x,i)=>x+centre[i]);g.line(centre,p,C.white,2);g.sphere(...p,.105,terminalColor,terminal)}};
export default function render({g:raw,t,p,extra,low}){const scale=.8,point=a=>a.map(x=>x*scale),g={sphere:(x,y,z,r,...a)=>raw.sphere(x*scale,y*scale,z*scale,r*scale,...a),line:(a,b,...r)=>raw.line(point(a),point(b),...r),text:(x,y,z,...a)=>raw.text(x*scale,y*scale,z*scale,...a),box:(x,y,z,a,b,c,...r)=>raw.box(x*scale,y*scale,z*scale,a*scale,b*scale,c*scale,...r),arrow:(a,b,...r)=>raw.arrow(point(a),point(b),...r),plot:o=>raw.plot(o)};
const m=extra.mode,x=p[0],v=chemistry(m,x),caption=(en,hi)=>g.text(-1.9,-1.45,0,B(en,hi));
if(m===0){let count=Math.round(x/9)*3;g.box(0,0,0,1.5,.8,.6,C.green);for(let i=0;i<count;i++)g.sphere(Math.sin(i*2.3+t*.2)*1.3,Math.cos(i*1.7+t*.3)*.6,Math.sin(i)*.4,.07,C.blue);caption('H2O: M = 18 g/mol; dots are samples','H2O: M = 18 g/mol; बिंदु नमूने हैं');}
else if(m===1){let used=Math.min(x/2,2);for(let i=0;i<6;i++){let y=(i%3-1)*.5,z=i>=3?.3:0;g.sphere(-1.6,y,z,.1,i<x?C.white:C.dark)}for(let i=0;i<2;i++)g.sphere(-.5,(i-.5)*.7,0,.15,C.pink);g.arrow([0,0,0],[.7,0,0],C.gold);for(let i=0;i<Math.round(used*2);i++)molecule(g,[1.2,(i-1.5)*.4,0],[[-.15,-.12,.1],[.15,-.12,.1]],C.pink);caption('2H2 + O2 → 2H2O; O2 = 2 mol','2H2 + O2 → 2H2O; O2 = 2 mol');}
else if(m===2){let height=.3+x/500;g.box(0,.3,0,1,height,.5,C.blue);for(let i=0;i<(low?12:24);i++)g.sphere(Math.sin(i*3+t*.1)*.85,.3+Math.cos(i*5)*height*.8,Math.sin(i)*.4,.055,C.gold);caption('n = 0.1 mol stays fixed','n = 0.1 mol स्थिर रहता है');}
else if(m===3){for(let n=1;n<=5;n++){let y=13.6/(n*n)/8-.8;g.line([-1.3,y,0],[1.3,y,0],n===x?C.gold:C.green,2);g.text(1.4,y,0,B('n='+n,'n='+n))}g.sphere(0,-v.energy/8-.8,0,.1,C.blue);caption('Hydrogen energies; level spacing symbolic','हाइड्रोजन ऊर्जा; स्तर दूरी सांकेतिक');}
else if(m===4){let points=[];for(let i=0;i<=90;i++)points.push([-2+4*i/90,.4*Math.sin(i/90*6*Math.PI*x-t*2),0]);path(g,points,C.blue,3);g.sphere(0,0,0,.12,C.gold,B('Electron symbol','इलेक्ट्रॉन प्रतीक'));caption('Matter wave is not a literal string','द्रव्य तरंग वास्तविक डोरी नहीं है');}
else if(m===5){if(x===0)g.sphere(0,0,0,.65,C.blue,B('s orbital','s कक्षक'));else{let count=x===1?2:4;for(let i=0;i<count;i++){let angle=i*Math.PI*2/count;g.sphere(.6*Math.cos(angle),.6*Math.sin(angle),0,.4,i%2?C.pink:C.blue)}g.sphere(0,0,0,.07,C.gold,B('Nucleus','नाभिक'))}caption('One representative orbital shape; colours = phase','1 प्रतिनिधि कक्षक आकृति; रंग = कला');}
else if([6,7,8].includes(m)){let radius=m===6?.4+.9*v.radiusIndex:m===8?.65*v.radiusIndex:.8;g.sphere(0,0,0,.14+.012*x,C.gold,B('Nucleus','नाभिक'));circle(g,0,0,radius,C.blue);for(let i=0;i<(m===8?10:8);i++){let a=i*Math.PI*2/(m===8?10:8);g.sphere(radius*Math.cos(a),radius*Math.sin(a),0,.055,C.blue)}caption(m===7?'Li → Ne ionisation data; symbolic electron cloud':m===8?'All ions/atom have 10 electrons':'Same-shell qualitative attraction model',m===7?'Li → Ne आयनन आँकड़े; सांकेतिक इलेक्ट्रॉन मेघ':m===8?'सभी आयन/परमाणु में 10 इलेक्ट्रॉन':'समान कोश का गुणात्मक आकर्षण मॉडल');}
else if(m===9||m===21){let index=Math.round(x);if(m===9&&index===0||m===21&&index===0)molecule(g,[0,0,0],[[.6,.6,.6],[-.6,-.6,.6],[-.6,.6,-.6],[.6,-.6,-.6]]);else if(m===9&&index===1){let c=.372,r=Math.sqrt(1-c*c),a=Array.from({length:3},(_,i)=>[r*Math.cos(i*Math.PI*2/3),r*Math.sin(i*Math.PI*2/3),c]);molecule(g,[0,0,0],a);g.sphere(0,0,-.9,.14,C.gold,B('Lone pair','एकाकी युग्म'));}else if(m===9&&index===2){let a=104.5*Math.PI/360;molecule(g,[0,0,0],[[-Math.sin(a),Math.cos(a),0],[Math.sin(a),Math.cos(a),0]],C.pink);g.sphere(-.35,-.7,.3,.13,C.gold);g.sphere(.35,-.7,-.3,.13,C.gold)}else if(m===21&&index===1)molecule(g,[0,0,0],Array.from({length:3},(_,i)=>[Math.cos(i*Math.PI*2/3),Math.sin(i*Math.PI*2/3),0]),C.blue,B('Bond direction','आबंध दिशा'));else{molecule(g,[0,0,0],[[-1,0,0],[1,0,0]],m===9?C.dark:C.blue,m===9?B('O','O'):B('Bond direction','आबंध दिशा'),m===9?C.pink:C.white);if(m===9){g.line([-.1,.07,0],[-.9,.07,0],C.white,2);g.line([.1,.07,0],[.9,.07,0],C.white,2)}}caption(m===9?['CH4: tetrahedral','NH3: trigonal pyramidal','H2O: bent','CO2: linear'][index]:['sp3: methane example','sp2: ethene carbon example','sp: ethyne carbon example'][index],m===9?['CH4: चतुष्फलकीय','NH3: त्रिकोणीय पिरामिडीय','H2O: कोणीय','CO2: रैखिक'][index]:['sp3: मेथेन का उदाहरण','sp2: एथीन कार्बन का उदाहरण','sp: एथाइन कार्बन का उदाहरण'][index]);}
else if(m===10){let a=x*Math.PI/360;g.arrow([0,.8,0],[Math.sin(a),.8-Math.cos(a),0],C.blue);g.arrow([0,.8,0],[-Math.sin(a),.8-Math.cos(a),0],C.green);g.arrow([0,.8,0],[0,.8-v.dipole,0],C.gold);caption('Two equal 1 D bond dipoles; vector sum','2 समान 1 D आबंध द्विध्रुव; सदिश योग');}
else if(m===11){for(let i=0;i<4;i++){g.line([-1.6,.3+i*.2,0],[-.3,.3+i*.2,0],C.green);g.sphere(-1.3,.3+i*.2,0,.06,C.blue);g.sphere(-.7,.3+i*.2,0,.06,C.blue)}for(let i=0;i<x;i++)g.sphere(.6+i%2*.5,-.2-Math.floor(i/2)*.3,0,.07,C.pink);g.line([.3,-.5,0],[1.6,-.5,0],C.pink);caption('Generic electron-count model; not an MO energy diagram','सामान्य इलेक्ट्रॉन गिनती मॉडल; MO ऊर्जा आरेख नहीं');}
else if(m===12){let h=.4+x*.2;g.box(0,0,0,1,h,.5,C.green);g.line([-1,-h,0],[1,-h,0],C.gold,4);g.arrow([0,-h,0],[0,-h-.35,0],C.gold);g.arrow([-1.9,0,0],[-1,0,0],C.pink);caption('q = +500 J; w = −PextΔV','q = +500 J; w = −PextΔV');}
else if(m===13||m===14){let pts=m===13?[[-1.5,-.7,0],[0,.2,0],[1.5,Math.max(-.8,Math.min(.9,-v.enthalpy/200)),0]]:[[-1.5,0,0],[1.5,Math.max(-1,Math.min(1,-v.gibbs/40)),0]];path(g,pts,C.green,3);pts.forEach((p,i)=>g.sphere(...p,.11,i===pts.length-1?C.gold:C.blue));g.arrow(pts[0],pts.at(-1),C.gold);caption(m===13?'Step 1 = −100 kJ/mol; add signed steps':'ΔH = 40 kJ/mol; ΔS = 0.100 kJ/(mol K)',m===13?'चरण 1 = −100 kJ/mol; चिह्न सहित चरण जोड़ें':'ΔH = 40 kJ/mol; ΔS = 0.100 kJ/(mol K)');}
else if(m===15){g.box(0,0,0,1.7,.9,.5,C.green);for(let i=0;i<(low?5:10);i++)g.sphere(-1.1+Math.sin(i*4+t*.2)*.4,Math.cos(i*3)*.7,0,.06,C.blue);for(let i=0;i<Math.round(x*(low?10:20));i++)g.sphere(.9+Math.sin(i*4+t*.2)*.4,Math.cos(i*3)*.7,0,.06,C.gold);g.arrow([-.3,-.5,0],[.3,-.5,0],C.blue);g.arrow([.3,-.2,0],[-.3,-.2,0],C.gold);caption(v.direction==='forward'?'Qc < Kc: forward tendency':v.direction==='reverse'?'Qc > Kc: reverse tendency':'Qc = Kc: dynamic equilibrium',v.direction==='forward'?'Qc < Kc: अग्र दिशा की प्रवृत्ति':v.direction==='reverse'?'Qc > Kc: पश्च दिशा की प्रवृत्ति':'Qc = Kc: गतिक साम्य');}
else if(m===16||m===17){g.box(0,0,0,1.4,.8,.5,C.blue);let fraction=Math.max(.08,Math.min(.8,v.dissociation*15));for(let i=0;i<20;i++){let px=Math.sin(i*4.2+t*.1)*1.2,py=Math.cos(i*2)*.6;g.sphere(px,py,Math.sin(i)*.3,.075,i/20<fraction?C.gold:C.green)}caption('Ion dots exaggerated; read the numerical concentration','आयन बिंदु बढ़ाकर दिखाए; संख्यात्मक सांद्रता पढ़ें');}
else if(m===18){g.sphere(0,0,0,.23,C.gold,B('M','M'));for(let i=0;i<x;i++){let a=i*2*Math.PI/x;g.line([0,0,0],[Math.cos(a),Math.sin(a),0],C.white,2);g.sphere(Math.cos(a),Math.sin(a),0,.16,C.pink,B('O: −2','O: −2'))}caption('MOx−: formal oxidation bookkeeping, not real-ion catalogue','MOx−: औपचारिक लेखा, वास्तविक आयनों की सूची नहीं');}
else if(m===19){g.sphere(-1.2,0,0,.3,C.blue,B('Zn → Zn2+','Zn → Zn2+'));g.sphere(1.2,0,0,.3,C.gold,B('Cu2+ → Cu','Cu2+ → Cu'));for(let i=0;i<Math.round(2*x);i++)g.sphere(-.7+((t*.3+i*.2)%1.4),-.5,0,.055,C.white);caption('1 Zn transfers 2 e−; sufficient Cu2+ available','1 Zn से 2 e−; पर्याप्त Cu2+ उपलब्ध');}
else if(m===20){for(let i=0;i<x;i++)g.sphere(-1.5+i%2*.35,-.6+Math.floor(i/2)*.25,0,.07,C.blue);for(let i=0;i<5;i++)g.sphere(1.1,-.6+i*.3,0,.07,C.gold);g.arrow([-.6,0,0],[.6,0,0]);caption('MnO4− + 8H+ + 5Fe2+ → Mn2+ + 4H2O + 5Fe3+','MnO4− + 8H+ + 5Fe2+ → Mn2+ + 4H2O + 5Fe3+');}
else if(m===22){let pts=Array.from({length:6},(_,i)=>[-1.8+i*.7,i%2*.25,0]);path(g,pts,C.white,3);pts.forEach((q,i)=>g.sphere(...q,.11,i===0?C.pink:C.blue));g.arrow([-.1,0,0],[-.1-v.effectIndex,0,0]);caption('Inductive effect attenuates: qualitative index only','प्रेरणिक प्रभाव घटता है: केवल गुणात्मक सूचकांक');}
else if(m===23){g.box(0,0,0,.7,1.2,.03,C.white);g.line([-.7,.9,.1],[.7,.9,.1],C.dark,2);g.line([-.7,-.9,.1],[.7,-.9,.1],C.blue,2);g.sphere(0,.9-x/8*1.8,.1,.1,C.pink,B('Solute spot','विलेय धब्बा'));caption('Solvent front = 8 cm; Rf = distance / 8','विलायक अग्र = 8 cm; Rf = दूरी / 8');}
else if(m===24){let pts=Array.from({length:x},(_,i)=>[(i-(x-1)/2)*.42,i%2*.28,0]);path(g,pts,C.white,3);pts.forEach(q=>g.sphere(...q,.12,C.dark));caption('Alkane skeleton; hydrogens omitted','ऐल्केन ढाँचा; हाइड्रोजन नहीं दिखाए');}
else if(m===25){g.sphere(0,0,-.45,.18,C.dark);g.sphere(0,0,.45,.18,C.dark);g.line([0,0,-.45],[0,0,.45],C.white,3);for(let side of[-1,1])for(let i=0;i<3;i++){let a=i*Math.PI*2/3+(side>0?x*Math.PI/180:0),q=[.8*Math.cos(a),.8*Math.sin(a),side*.65];g.line([0,0,side*.45],q,C.white,2);g.sphere(...q,.09,side<0?C.blue:C.gold)}caption('Ethane torsion; energy index is schematic','एथेन का मरोड़; ऊर्जा सूचकांक सांकेतिक');}
else{let reactants=['CH2=CH2 + H2','CH4 + Cl2','C6H6 + HNO3'],products=['CH3−CH3','CH3Cl + HCl','C6H5NO2 + H2O'];g.text(-1.8,-.5,0,B(reactants[x],reactants[x]));g.arrow([-1,0,0],[1,0,0]);g.text(-1.8,.7,0,B(products[x],products[x]));caption(['Ni: addition','Light: first substitution stage','Acid-catalysed substitution'][x],['Ni: संकलन','प्रकाश: प्रथम प्रतिस्थापन चरण','अम्ल उत्प्रेरित प्रतिस्थापन'][x]);}
const s=readingSpec[m],rows=[read(s[0],s[1],fmt(v[s[2]]),s[3])];if(secondary[m]){let a=secondary[m];rows.push(read(a[0],a[1],fmt(v[a[2]]),a[3]))}
if(![5,9,18,21,26].includes(m)){let[lo,hi]=extra.bounds||[1,5],points=[];for(let i=0;i<=80;i++){let a=lo+(hi-lo)*i/80;if(m===7||m===24)a=Math.round(a);points.push([a,chemistry(m,a)[s[2]]])}let values=points.map(q=>q[1]),min=Math.min(0,...values),max=Math.max(0,...values);g.plot({title:B('Parameter relationship','नियंत्रक राशि का संबंध'),xMin:lo,xMax:hi,yMin:min,yMax:max===min?max+1:max*1.08,points,marker:[x,v[s[2]]]})}return rows;
}
